fn choose_odd(v: &Vec<u64>) -> usize {
    // Find the first element that is odd (least significant bit is 1)
    // We can safely unwrap because the problem guarantees at least one odd element exists.
    v.iter()
     .position(|&x| x & 1 == 1)
     .unwrap()
}

